from pathlib import Path
p=Path('/private/tmp/openui-selectors-w2-evidence')
s=(p/'run-overrides.mjs').read_text();s=s[:s.index('try{browser=await')]
s+=r'''
const missing=JSON.parse(await fs.readFile(root+'/unmatched-default-targets.json','utf8')),seen=new Set(),captures=[];
async function capture(p,selector){return p.locator(selector).evaluate(el=>{const props=['display','position','boxSizing','color','backgroundColor','padding','border','borderRadius','gap','fontSize','fontFamily','fontWeight','lineHeight','objectFit','overflow','cursor'];return [el,...el.querySelectorAll('*')].map(e=>{const s=getComputedStyle(e);return{tag:e.tagName,text:e.childElementCount?null:e.textContent?.slice(0,50),role:e.getAttribute('role'),state:e.getAttribute('data-state'),styles:Object.fromEntries(props.map(k=>[k,s[k]])),size:[e.offsetWidth,e.offsetHeight]};});});}
async function collect(p){for(const h of await p.evaluate(hooks=>hooks.filter(h=>!!document.querySelector('.'+h)),missing.map(x=>x.hook)))seen.add(h);}
async function override(p,selector,property,wanted){const detail=await p.evaluate(async({selector,property,wanted})=>{const e=document.querySelector(selector);if(!e)return{selector,property,missing:true};const rules=[];function walk(rs){for(const r of rs){if(r.selectorText&&r.style&&e.matches(r.selectorText)&&r.style.getPropertyValue(property))rules.push({selector:r.selectorText,value:r.style.getPropertyValue(property),priority:r.style.getPropertyPriority(property)});if(r.cssRules)walk(r.cssRules);}}for(const s of document.styleSheets)try{walk(s.cssRules)}catch{}const before=getComputedStyle(e).getPropertyValue(property),s=document.createElement('style');s.textContent=selector+'{'+property+':'+wanted+'}';document.head.append(s);getComputedStyle(e).display;await new Promise(r=>requestAnimationFrame(r));await Promise.all(e.getAnimations().filter(a=>a.constructor.name==='CSSTransition').map(a=>a.finished.catch(()=>{})));const actual=getComputedStyle(e).getPropertyValue(property);s.remove();return{selector,property,before,wanted,actual,ownedCompetingRules:rules,pass:actual===wanted};},{selector,property,wanted});check('ordinary matching override/'+selector+'/'+property,detail.pass,detail);}
try{browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
// A contextual part requires the same documented ancestor context as the default rule.
{const p=await browser.newPage();await p.goto(origin+'/candidate-small-Tabs/index.html');await p.waitForFunction(()=>window.ready);await override(p,'.openui-tabs-container .openui-tabs-list-styled','box-sizing','content-box');await p.close();}
for(const framework of ['plain','tailwind3','tailwind4'])for(const order of ['before','after']){const config={framework,order,globOrder:order},pair={};for(const arm of ['baseline','candidate']){const p=await browser.newPage({viewport:{width:1280,height:900}}),pending=[],pageErrors=[];p.on('pageerror',e=>pageErrors.push(String(e)));await p.route('**/pending.svg',r=>pending.push(r));await p.goto(origin+'/'+arm+'-extra/index.html?'+new URLSearchParams(config),{waitUntil:'domcontentloaded'});await p.waitForFunction(()=>window.ready&&document.querySelectorAll('[data-family]').length===6);await p.waitForSelector('.openui-image-block-loader');await settle(p);const states={};states.loader=await capture(p,'.openui-image-block-loader');await collect(p);check(arm+'/'+framework+'/'+order+'/pending-image-loader',await p.locator('[data-family=ImageBlock] img').evaluate(e=>!e.complete));for(const r of pending)await r.fulfill({contentType:'image/svg+xml',body:'<svg xmlns="http://www.w3.org/2000/svg" width="64" height="40"><rect width="64" height="40" fill="#345678"/></svg>'});await p.unroute('**/pending.svg');await p.waitForSelector('.openui-image-block-loader',{state:'detached'});check(arm+'/'+framework+'/'+order+'/image-load-completes',await p.locator('[data-family=ImageBlock] img').evaluate(e=>e.complete&&e.naturalWidth===64));
for(const mode of ['light','dark','nested']){await p.evaluate(m=>window.renderMode(m),mode);await settle(p);await collect(p);states[mode]={};
await p.locator('#tooltip-trigger').hover();await p.waitForSelector('.openui-tooltip-content');await settle(p);states[mode].tooltip=await capture(p,'.openui-tooltip-content');await collect(p);if(arm==='candidate'){await override(p,'.openui-tooltip-wrapper-content','border-radius','19px');await override(p,'.openui-tooltip-wrapper-heading','color','rgb(1, 2, 3)');}await p.mouse.move(1270,890);await p.keyboard.press('Escape');await p.waitForSelector('.openui-tooltip-content',{state:'detached'});
await p.locator('[data-family=Citation] .openui-citation').click();await p.waitForSelector('.openui-citation-tooltip');await settle(p);states[mode].citation=await capture(p,'.openui-citation-tooltip');await collect(p);if(arm==='candidate'){await override(p,'.openui-citation-tooltip-styled','border-radius','19px');await override(p,'.openui-citation-item-title','color','rgb(1, 2, 3)');}await p.locator('.openui-citation-item').first().focus();await p.keyboard.press('Enter');await p.waitForSelector('.openui-citation-tooltip',{state:'detached'});check(arm+'/'+framework+'/'+order+'/'+mode+'/citation-keyboard-close',await p.locator('.openui-citation-tooltip').count()===0);
await p.locator('[data-family=ImageGallery] .openui-gallery__image').first().click();await p.waitForSelector('.openui-gallery__modal');await settle(p);await p.waitForTimeout(350);const dialog=p.getByRole('dialog');states[mode].gallery=await capture(p,'.openui-gallery__modal');await collect(p);check(arm+'/'+framework+'/'+order+'/'+mode+'/dialog-semantics',await dialog.getAttribute('aria-modal')==='true');await dialog.getByRole('button',{name:'Gallery 1',exact:true}).focus();await p.keyboard.press('Enter');check(arm+'/'+framework+'/'+order+'/'+mode+'/gallery-keyboard-select',await dialog.locator('.openui-gallery__modal-main img').getAttribute('alt')==='Gallery 1');if(arm==='candidate'){await override(p,'.openui-image-gallery-gallery-modal-content','border-radius','19px');await override(p,'.openui-image-gallery-gallery-modal-thumbnail.openui-image-gallery-gallery-modal-active-thumbnail','border-top-color','rgb(3, 4, 5)');}
const right=dialog.getByRole('button',{name:'Scroll images right'});if(await right.count()){await right.click();await p.waitForTimeout(650);check(arm+'/'+framework+'/'+order+'/'+mode+'/gallery-scroll',await dialog.locator('.openui-gallery__modal-carousel').evaluate(e=>e.scrollLeft>0));await collect(p);}else check(arm+'/'+framework+'/'+order+'/'+mode+'/gallery-overflow-control',false);await dialog.getByRole('button',{name:'Close gallery'}).click();await p.waitForSelector('.openui-gallery__modal',{state:'detached'});check(arm+'/'+framework+'/'+order+'/'+mode+'/gallery-close',await p.locator('.openui-gallery__modal').count()===0);
}
check(arm+'/'+framework+'/'+order+'/host-import-isolation',await p.evaluate(()=>JSON.stringify(window.hostBefore)===JSON.stringify(window.hostAfterImport)));await p.evaluate(()=>window.hostUpdate());check(arm+'/'+framework+'/'+order+'/stock-glob-update',await p.locator('.host-sentinel').evaluate(e=>getComputedStyle(e).color==='rgb(7, 8, 9)'));check(arm+'/'+framework+'/'+order+'/page-errors',pageErrors.length===0,pageErrors);pair[arm]=states;await p.close();}
for(const mode of ['loader','light','dark','nested']){const pass=equal(pair.baseline[mode],pair.candidate[mode]);check(framework+'/'+order+'/'+mode+'/paired-parity',pass,pass?undefined:{baseline:pair.baseline[mode],candidate:pair.candidate[mode]});}captures.push({config,pair});await fs.writeFile(root+'/extra-progress.json',JSON.stringify({configs:captures.length,checks:checks.length,failed:checks.filter(x=>!x.pass).map(x=>x.name)}));}
check('all-26-transient-portal-hooks-observed',seen.size===missing.length,{seen:[...seen],missing:missing.filter(x=>!seen.has(x.hook))});await fs.writeFile(root+'/extra-results.json',JSON.stringify({browser:browser.version(),checks,captures,seen:[...seen]},null,2));console.log(JSON.stringify({checks:checks.length,passed:checks.filter(x=>x.pass).length,failed:checks.filter(x=>!x.pass).map(x=>x.name),seen:seen.size}));
}finally{if(browser)await browser.close();await new Promise(r=>server.close(r));await fs.writeFile(root+'/extra-session-closed.json',JSON.stringify({time:new Date().toISOString(),browserClosed:true,serverClosed:true}));}
'''
(p/'run-extra.mjs').write_text(s)
